        internal static void RunNavigation(Action<string,Action> check,string assets,Form owner)
        {
            string programs=Path.Combine(Path.GetDirectoryName(assets),"Programs");var source=File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN"));Func<PracticeMapStartup> startup=delegate{return PracticeMapStartup.CreateBssb202(programs,source,731);};
            check("Active navigation form applies replan waiting and final-goal completion on fresh copies",delegate{
                using(var f=new PracticeGoalRouteStudy(programs,startup(),true)){Show(f,owner);Need(f.NavigationOnly&&Find<ComboBox>(f,"goalRouteProfile").Items.Count==5&&!Find<Button>(f,"goalRouteBuild").Visible&&Find<Button>(f,"goalRouteNavigationApply").Enabled,"Navigation-only controls");Find<Button>(f,"goalRouteNavigationApply").PerformClick();var r=f.StudyState.NavigationResult;Need(r.Outcome==PracticeActiveNavigationOutcome.Replanned&&r.NavigationVisits==250&&r.GridFunctionVisits==2&&r.WaypointFunctionVisits==1&&BitConverter.ToInt16(r.CopyFleetPool(),16*492+40)==110&&f.StudyState.OriginX==100&&!Find<Button>(f,"goalRouteNavigationApply").Enabled,"Fresh replan");var applied=f.StudyState;Find<ComboBox>(f,"goalRouteNavigationMode").SelectedIndex=0;Need(Object.ReferenceEquals(applied,f.StudyState),"Pending mode changed applied input");Find<Button>(f,"goalRouteReset").PerformClick();Find<Button>(f,"goalRouteNavigationApply").PerformClick();Need(f.StudyState.NavigationResult.Outcome==PracticeActiveNavigationOutcome.Waiting&&!f.StudyState.HasGridOutput,"Waiting built a grid");Load(f,4);Need(Find<ComboBox>(f,"goalRouteProfile").Text.Contains("complete navigation"),"Navigation label incorrectly claims task pop");Find<Button>(f,"goalRouteNavigationApply").PerformClick();Need(f.StudyState.NavigationResult.Outcome==PracticeActiveNavigationOutcome.CompletedGoal&&BitConverter.ToInt32(f.StudyState.Backing.CopyTaskRecord(16),304)==0&&BitConverter.ToInt32(f.StudyState.Backing.CopyTaskRecord(16),200)==4&&!f.StudyState.HasGridOutput,"Final completion confused with task pop");f.Close();}
            });
            check("Active navigation form preserves double-clear failure and intermediate-arrival results with reachable controls",delegate{
                using(var f=new PracticeGoalRouteStudy(programs,startup(),true)){Show(f,owner);Load(f,1);Find<Button>(f,"goalRouteNavigationApply").PerformClick();var r=f.StudyState.NavigationResult;Need(r.Outcome==PracticeActiveNavigationOutcome.Replanned&&r.InitialReplan.Outcome==PracticeGoalRouteOutcome.RouteUnavailable&&r.GridFunctionVisits==2&&r.Grid.Cell(13,12)==254,"Failed replan double clear");Find<Button>(f,"goalRouteReset").PerformClick();Find<ComboBox>(f,"goalRouteNavigationMode").SelectedIndex=2;Find<Button>(f,"goalRouteNavigationApply").PerformClick();r=f.StudyState.NavigationResult;Need(r.Outcome==PracticeActiveNavigationOutcome.ReachedWaypoint&&r.GridFunctionVisits==1&&r.Grid.Cell(12,12)==255&&BitConverter.ToInt16(r.CopyFleetPool(),16*492+40)==100,"Blocked intermediate arrival");f.Size=f.MinimumSize;Application.DoEvents();var scroll=Find<Panel>(f,"goalRouteScroll");var close=Find<Button>(f,"goalRouteClose");scroll.ScrollControlIntoView(close);Application.DoEvents();var box=scroll.RectangleToClient(close.RectangleToScreen(close.ClientRectangle));Need(scroll.AutoScroll&&box.Bottom<=scroll.ClientSize.Height+2,"Navigation close unreachable");f.Close();}
