            File.WriteAllText(Path.Combine(destination,"Scope.txt"),"Eight actual-form active-navigation previews:prepared,replan,wait,doubleclear,arrival,finalgoal,minimum,minimumdetails. Original whole prephase in a controlled copied profile;fixedfleet/suppliedclock;no actualworldmovement/ownerdriver/pacing/audio/settings changes. Physical DPI/input remains a hands-on check.\r\n");return 0;
        }
